<script setup>
import * as yup from 'yup'
import { useForm } from 'vee-validate'
import { i18nRender } from '@/locales'
import { getSensitiveModelList } from '@/services/models'
import { getSensitiveConfig, setSensitiveConfig } from '@/services/sensitive'
import useChatStore from '@/stores/chat'
import { useToast } from 'primevue/usetoast'
import { useWebview } from '@/composables/useWebview'

const { openExternalLink } = useWebview()

const toast = useToast()

const ChatStore = useChatStore()

const props = defineProps({
  pluginId: {
    type: [String, Number],
    default: 0
  },
  initParams: {
    type: Object,
    default: () => null
  },
  isSettingDefault: {
    type: Boolean,
    default: false
  }
})

const typeList = reactive({
  local_words: false,
  baidu_api: true,
  local_model: false
})

const schema = computed(() =>
  yup.object({
    // local_word_interval_tokens: typeList.local_words ? yup.string().required(i18nRender('lang.noEmpty')) : yup.string(),
    baidu_api_interval_tokens: typeList.baidu_api ? yup.string().required(i18nRender('lang.noEmpty')) : yup.string(),
    baidu_api_api_key: typeList.baidu_api ? yup.string().required(i18nRender('lang.noEmpty')) : null,
    baidu_api_secret_key: typeList.baidu_api ? yup.string().required(i18nRender('lang.noEmpty')) : null,
    local_model_model_id: typeList.local_model ? yup.string().required(i18nRender('lang.noEmpty')) : null,
    local_model_interval_tokens: typeList.local_model ? yup.string().required(i18nRender('lang.noEmpty')) : yup.string()
  })
)

const { defineField, handleSubmit, errors } = useForm({
  validationSchema: schema,
  initialValues: {
    local_word_interval_tokens: 10,
    baidu_api_interval_tokens: 20,
    baidu_api_api_key: '',
    baidu_api_secret_key: '',
    local_model_model_id: null,
    local_model_interval_tokens: 20,
    local_model_filter_model_list: []
  }
})

const sensitiveTypes = reactive({
  local_words: {
    open: false,
    form: {
      interval_tokens: defineField('local_word_interval_tokens')[0]
    }
  },
  baidu_api: {
    open: true,
    form: {
      interval_tokens: defineField('baidu_api_interval_tokens')[0],
      api_key: defineField('baidu_api_api_key')[0],
      secret_key: defineField('baidu_api_secret_key')[0]
    }
  },
  local_model: {
    open: false,
    form: {
      model_id: defineField('local_model_model_id')[0],
      interval_tokens: defineField('local_model_interval_tokens')[0],
      filter_model_list: [
        { name: i18nRender('lang.politic'), type: 'politic', active: true, threshold: 0.8 },
        { name: i18nRender('lang.porn'), type: 'porn', active: true, threshold: 0.8 },
        { name: i18nRender('lang.insult'), type: 'insult', active: true, threshold: 0.8 },
        { name: i18nRender('lang.violence'), type: 'violence', active: true, threshold: 0.8 }
      ]
    }
  }
})

function getConfig() {
  function setConfig(data) {
    ;(data.style_filter_list || []).forEach((item) => {
      typeList[item] = true
      switch (item) {
        case 'local_words':
          sensitiveTypes.local_words.form.interval_tokens = 10
          break
        case 'baidu_api':
          sensitiveTypes.baidu_api.form.interval_tokens = data.baidu_api.interval_tokens
          sensitiveTypes.baidu_api.form.api_key = data.baidu_api.api_key
          sensitiveTypes.baidu_api.form.secret_key = data.baidu_api.secret_key
          break
        case 'local_model':
          sensitiveTypes.local_model.form.model_id = 3
          sensitiveTypes.local_model.form.interval_tokens = 10
          sensitiveTypes.local_model.form.filter_model_list.forEach((style) => {
            const current = data.local_model.filter_model_list.find((_style) => _style.type === style.type)
            style.active = !!current
            style.threshold = current ? current.threshold : 0.8
          })
      }
    })
  }

  if (props.isSettingDefault) {
    return new Promise((resolve) => {
      setConfig(props.initParams)
      resolve(props.initParams)
    })
  } else {
    return getSensitiveConfig({
      session_id: ChatStore.currentConversationId,
      plugin_id: props.pluginId
    }).then((res) => {
      const { resData } = res
      setConfig(resData)
    })
  }
}

const modelList = ref([])

function getModelList() {
  return getSensitiveModelList().then(async (res) => {
    await getConfig()
    modelList.value = res.resData
    if (modelList.value.length) {
      sensitiveTypes.local_model.form.model_id = modelList.value[0]?.id || ''
    }
  })
}

getModelList()

const filterModelListDisabled = computed(() => sensitiveTypes.local_model.form.filter_model_list.filter((item) => item.active).length <= 1)

const submit = handleSubmit(() => {
  // console.log(sensitiveTypes.local_words.form.interval_tokens)
  const data = {
    session_id: ChatStore.currentConversationId,
    plugin_id: props.pluginId,
    style_filter_list: Object.keys(sensitiveTypes).filter((item) => typeList[item]),
    local_words: sensitiveTypes.local_words.form,
    baidu_api: sensitiveTypes.baidu_api.form,
    local_model: Object.assign({}, sensitiveTypes.local_model.form, {
      filter_model_list: sensitiveTypes.local_model.form.filter_model_list
        .filter((item) => item.active)
        .map((item) => ({
          type: item.type,
          threshold: item.threshold
        }))
    })
  }
  console.log(data)
  setSensitiveConfig(data).then(() => {
    getConfig()
    toast.add({ severity: 'success', summary: i18nRender('lang.saveSuccess'), life: 3000 })
  })
})

const exposeSubmit = handleSubmit(() => {
  const data = {
    session_id: ChatStore.currentConversationId,
    plugin_id: props.pluginId,
    style_filter_list: Object.keys(sensitiveTypes).filter((item) => typeList[item]),
    local_words: sensitiveTypes.local_words.form,
    baidu_api: sensitiveTypes.baidu_api.form,
    local_model: Object.assign({}, sensitiveTypes.local_model.form, {
      filter_model_list: sensitiveTypes.local_model.form.filter_model_list
        .filter((item) => item.active)
        .map((item) => ({
          type: item.type,
          threshold: item.threshold
        }))
    })
  }
  console.log(data)
  return data
})

defineExpose({
  exposeSubmit
})

const BaiduseqLink = () => {
  const url = 'https://ai.baidu.com/censoring'
  openExternalLink(url) //  使用封装函数
}
