import request from '@/hooks/useHttp'

export function getSensitiveConfig(params) {
  return request({
    method: 'get',
    url: '/plugin-param/sensitive/list',
    params
  })
}

export function setSensitiveConfig(data) {
  return request({
    method: 'put',
    url: `/plugin-param/sensitive/update/${data.session_id}`,
    data
  })
}
